      "relation": "PROPOSES",
      "target": "failure mode diagnosis method",
      "target_type": "method",
      "evidence": "we propose a novel failure mode diagnosis method that leverages a dimension reduction technique called UMAP (Uniform Manifold Approximation and Projection) to project and visualize each unit's degradation trajectory into a lower dimension"
    },
    {
      "relation": "PROPOSES",
      "target": "time series-based clustering method",
